# -*- coding: utf-8 -*-
"""КОЛО-РОЛІ-3 (наряд 2.1-А): проєкт «тон у вікні» без підключення на кольорових речах каталогу. Прототип (а'): (1) край дуги —
рівно 0.5: Φ((пів − d)/σ) (нині 0.5 − Φ(−2·пів/σ), точка на краю «поза» зрізом 0.5); (2) згасання без підлоги `СІГМА_МЕЖІ` — кут
сталої ΔH* `ΔH_КРАЮ`, не далі `ЗАПАС_ПРИГЛУШЕНИХ`; (3) K-PAL-17: тон — та сама сила (половина на кінці згасання — межа суду),
очі — `сила_сім_ї_очей` («акцент» — «так» суду). Друкує зміни суду й `описує_річ` (0.05), пулу/носіїв (0.5), зону 0.05–0.5,
K-PAL-17 ДО → ПІСЛЯ (стенд, ж1–ж9) і розбіжність його тону з судом. Запуск із джерела/: python3 проби/коло_ролі_проєкт.py"""
import json, glob, math, sys, collections as K; sys.path.insert(0, ".")
import bridge as B, colorspace as cs, колір_річ as КР, колір_відношення as КВ, палітра_схеми as ПС, palettes as ПЛ, річ_з_фото as РФ
вх0 = json.load(open("стенд_вх.json", encoding="utf-8")); B.виклик("запити", json.dumps(вх0, ensure_ascii=False))
речі = [r for r in B.каталог_останнього_пакета() if КР.межі_кольору(r) and КР.нейтраль_меж(r) == "ні"]
ролі = {д for i in range(12) for з in ПС.СХЕМИ.values() for д in з["тон"](cs.з_кола_художника(30.0 * i)).values() if isinstance(д, tuple)}
жінки = [вх0] + [dict(вх0, шкіра=Ж["skin"][0], волосся=Ж["hair"], очі=Ж["eyes"]) for Ж in
                 (json.load(open(f, encoding="utf-8")) for f in sorted(glob.glob("../аудит/проби/жінки/ж*.json")))]
П = [ПЛ.палітра_практична(B._features(вх)[0]) for вх in жінки]
вікна = {tuple(д) for п in П for с, дд in п["вікна"]["сім_ї"].items() if с != "очі" for д in дд}
край = lambda d, пів, σ: 0.5 * (1.0 + math.erf((пів - d) / (σ * math.sqrt(2.0))))
згасання = lambda C: min(math.degrees(2 * math.asin(min(1.0, КВ.ΔH_КРАЮ / (2 * max(C, 1e-6))))), КВ.ЗАПАС_ПРИГЛУШЕНИХ) / КВ._Z_КІНЦЯ
def сила_в_дузі(р, дуга):
    if р is None or р["дуга"] is None: return КВ.НЕВІДОМО
    (ц, пів), σ = КВ._параметри_дуги(дуга), (згасання(р["C"][0]), згасання(р["C"][1])); д = КВ._розкид_дуг(р["дуга"], (ц, ц))
    return (min(край(д[1], пів, с) for с in σ), max(край(д[0], пів, с) for с in σ))
точка = lambda C, h, дуга: край(КВ._кут(h, КВ._параметри_дуги(дуга)[0]), КВ._параметри_дуги(дуга)[1], згасання(C))
Л, стар = K.Counter(), (КВ.сила_в_дузі, КВ.сила_точки_в_дузі)
for стан in ("ДО", "ПІСЛЯ"):
    КВ.сила_в_дузі, КВ.сила_точки_в_дузі = стар if стан == "ДО" else (сила_в_дузі, точка); КР._ДУГИ_ВІКНА.clear(); В = Л.setdefault(стан, {})
    for x, (мн, дд) in ((x, м) for x in речі for м in (("ролі", ролі), ("вікна", вікна))):
        В.update({(x["id"], д): (КР.у_дугах_кола(x, [д], 0.5), КР.у_дугах_кола(x, [д], КВ.КІНЕЦЬ_ЗГАСАННЯ), мн, КР.не_вимір(x) is None) for д in дд})
for к, (п5, п05, мн, вим) in Л["ДО"].items():
    н5, н05 = Л["ПІСЛЯ"][к][:2]; вд = "вим" if вим else "сл"
    Л[(мн, вд, "суд 0.05", п05 + "→" + н05)] += п05 != н05; Л[(мн, вд, "пул/носії 0.5", п5 + "→" + н5)] += п5 != н5
    Л[(мн, вд, "зона ДО")] += п5 != п05; Л[(мн, вд, "зона ПІСЛЯ")] += н5 != н05
for п, x in ((п, x) for п in П for x in речі if КР.не_вимір(x) is None and КР.нейтраль(tuple(x["lab"])) is None):
    до, р, (L, C, h) = РФ.членство_в_палітрі(x["lab"], п), КР.запис_кольору(x), cs.lch(tuple(x["lab"])); со = КВ.сила_сім_ї_очей(р, п["вікна"]["очі"])[0]
    дуги = [д for с, дд in п["вікна"]["сім_ї"].items() if с != "очі" for д in дд]; чh = min(1.0, 0.5 * max(точка(C, h, д) for д in дуги) / КВ.КІНЕЦЬ_ЗГАСАННЯ)
    чh = max(чh, 1.0 if со >= 0.5 else со); с = cs.soft(L, *п["вікна"]["L"], РФ.ШИРИНА_L) * cs.soft(C, *п["вікна"]["C"], РФ.ШИРИНА_C) * чh
    пс = "у палітрі" if с >= РФ.У_ПАЛІТРІ else "на межі" if с >= РФ.НА_МЕЖІ else "поза палітрою"; акц = "акцент" if со >= 0.5 else "колір"
    Л[("K-PAL-17 стан", до["стан"] + "→" + пс)] += до["стан"] != пс; Л[("K-PAL-17 роль очей", до["роль"][:6] + "→" + акц)] += до["роль"][:6] != акц
    Л[("K-PAL-17 тон ≠ суд", "")] += (чh >= 0.5) != (КР.у_вікнах_меж(x, (0, 100), (0, 1000), дуги, очі=п["вікна"]["очі"]) == "так")
print("кольорових речей %d, дуг ролей %d, вікон %d, жінок %d" % (len(речі), len(ролі), len(вікна), len(П)))
for к, v in sorted((к, v) for к, v in Л.items() if к not in ("ДО", "ПІСЛЯ") and (v or к[0] == "K-PAL-17 тон ≠ суд")): print("  %-58s %6d" % (" · ".join(к), v))
